int eval_rpn(const std::vector<std::string>& tokens) {
    std::stack<int> st;
    for (const auto& tok : tokens) {
        if (tok=="+"||tok=="-"||tok=="*"||tok=="/") {
            int b = st.top(); st.pop(); int a = st.top(); st.pop();
            if (tok=="+") st.push(a+b); else if (tok=="-") st.push(a-b);
